import unittest

class Behavior(unittest.TestCase):
    def test_contract(self):
        from timeline import insert_at
        cases = [([],7,0), ([10,20,20,40],20,1), ([10,20,20,40],30,3),
                 ([10,20,20,40],5,0), ([10,20,20,40],50,4),
                 ([7,7,7],7,0), ([7],7,0), ([-4,0,0,9],0,1)]
        for values, incoming, expected in cases:
            with self.subTest(values=values, incoming=incoming):
                before = values[:]
                self.assertEqual(insert_at(values, incoming), expected)
                self.assertEqual(values, before)

    def test_logarithmic_access(self):
        from timeline import insert_at
        class ReadBudget:
            def __init__(self):
                self.reads = 0
            def __len__(self):
                return 4096
            def __getitem__(self, index):
                if isinstance(index, slice):
                    indices = range(*index.indices(len(self)))
                    self.reads += len(indices)
                    return [i // 3 for i in indices]
                self.reads += 1
                if not 0 <= index < len(self):
                    raise IndexError(index)
                return index // 3
        for incoming in [-1, 0, 1, 517, 1365, 1366]:
            values = ReadBudget()
            self.assertEqual(insert_at(values, incoming), min(4096, max(0, incoming * 3)))
            self.assertLessEqual(values.reads, 128, 'Use binary search, not a linear scan or copy')

if __name__ == "__main__":
    unittest.main()

